.ui-root .ui-breadcrumb { display: flex; flex-wrap: wrap; align-items: center; gap: calc(var(--ui-space) * 2); font-size: 14px; line-height: 1.5; color: var(--ui-text); padding: calc(var(--ui-space) * 2) 0; }
