/* Top bar and menu */
.ui-shell { display: grid; grid-template-columns: 240px minmax(0, 1fr); grid-template-rows: 64px minmax(0, 1fr); grid-template-areas: "side top" "side main"; min-height: 100vh; background: var(--ui-bg); color: var(--ui-text); font-family: var(--ui-font); font-size: 15px; line-height: 1.5; }
