.ui-nav-item { display: block; padding: 8px 12px; border-radius: var(--ui-radius-sm); font-size: 0.875rem; font-weight: 500; color: var(--ui-text); text-decoration: none; border: 1px solid transparent; transition: background-color 150ms ease, color 150ms ease; }
